using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
public static class Lift05FullNativeCheck {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static object G(object x,string n)=>x.GetType().GetField(n,F).GetValue(x);
 public static void Check(Assembly asm,string root,int lod,object plan,float delta,int meshIndex=0){
 using(var reader=new BinaryReader(File.OpenRead(Path.Combine(root,(meshIndex==0?"raw/lod":"glass/lod")+lod+".bin")))){
 int vc=reader.ReadInt32(),ic=reader.ReadInt32(),ac=reader.ReadInt32();var ix=new int[ic];for(int i=0;i<ic;i++)ix[i]=reader.ReadInt32();var attrs=new Dictionary<VertexAttribute,byte[]>();var ds=new List<VertexAttributeDescriptor>();for(int i=0;i<ac;i++){var a=(VertexAttribute)reader.ReadInt32();var fmt=(VertexAttributeFormat)reader.ReadInt32();int dim=reader.ReadInt32(),len=reader.ReadInt32();attrs.Add(a,reader.ReadBytes(len));ds.Add(new VertexAttributeDescriptor(a,fmt,dim,0));}
 var mesh=new Mesh();mesh.SetVertexBufferParams(vc,ds.ToArray());int stride=mesh.GetVertexBufferStride(0);var raw=new byte[vc*stride];foreach(var a in attrs){int size=a.Value.Length/vc,off=mesh.GetVertexAttributeOffset(a.Key);for(int v=0;v<vc;v++)Buffer.BlockCopy(a.Value,v*size,raw,v*stride+off,size);}mesh.SetVertexBufferData(raw,0,0,raw.Length);mesh.SetIndices(ix,MeshTopology.Triangles,0);
 object[] args={"Lift05 all-face native",mesh,plan,3,null,null,false};var type=asm.GetType("BridgeBuilder.Bridges.MovableStructureModel",true);if(!(bool)type.GetMethod("TryBuild",F).Invoke(null,args))throw new Exception("Native Build "+args[5]);var model=args[4];Mesh upload=null;try{
 upload=(Mesh)model.GetType().GetMethod("ToUnityMesh",F).Invoke(model,new object[]{true});var fr=((IEnumerable)G(plan,"Fragments")).Cast<object>().ToDictionary(x=>(int)G(x,"Triangle"),x=>(int[])G(x,"Indices"));var mask=((bool[][])G(plan,"RemoveTriangles"))[0];var sequence=new List<int>();for(int face=0;face<ic/3;face++){if(fr.TryGetValue(face,out var ff))sequence.AddRange(ff);else if(!mask[face])sequence.AddRange(ix.Skip(face*3).Take(3));}
 var triangles=upload.triangles;var positions=upload.vertices;var planned=(Vector3[])G(plan,"Positions");if(triangles.Length!=sequence.Count)throw new Exception("Final index coverage changed");for(int i=0;i<triangles.Length;i++)if(!positions[triangles[i]].Equals(planned[sequence[i]]))throw new Exception("Final position changed");
 using(var view=Mesh.AcquireReadOnlyMeshData(upload)){foreach(var a in attrs){if(a.Key==VertexAttribute.Position)continue;if(a.Key==VertexAttribute.TexCoord0 && meshIndex==0){var uvs=new List<Vector4>();upload.GetUVs(0,uvs);for(int j=0;j<triangles.Length;j++){int original=sequence[j];if(original>=vc)continue;float u=Mathf.HalfToFloat(BitConverter.ToUInt16(a.Value,original*4)),v=Mathf.HalfToFloat(BitConverter.ToUInt16(a.Value,original*4+2));if(uvs[triangles[j]].x!=u||uvs[triangles[j]].y!=v)throw new Exception("Promoted original UV value changed");}Debug.Log("Lift05 UV native source Float16x2 upload="+upload.GetVertexAttributeFormat(a.Key)+"x"+upload.GetVertexAttributeDimension(a.Key)+" exact decoded original values verified");continue;}int stream=upload.GetVertexAttributeStream(a.Key),us=upload.GetVertexBufferStride(stream),uo=upload.GetVertexAttributeOffset(a.Key),size=a.Value.Length/vc;var bytes=view[0].GetVertexData<byte>(stream);for(int i=0;i<triangles.Length;i++){int original=sequence[i];if(original>=vc)continue;for(int k=0;k<size;k++)if(bytes[triangles[i]*us+uo+k]!=a.Value[original*size+k])throw new Exception("Original raw attribute changed "+a.Key);}}}
 Lift05RetileSlots.Check(asm,root,lod,plan,model,delta,meshIndex);Debug.Log($"PASS Lift05 full TryBuild/upload lod={lod} triangles={triangles.Length/3}; complete indices/positions; original raw packed normal/tangent/UV/bone");
 }finally{if(upload!=null)UnityEngine.Object.DestroyImmediate(upload);(model as IDisposable)?.Dispose();UnityEngine.Object.DestroyImmediate(mesh);}
 }}
